import{_ as a,o as t,c as r,a6 as s}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{"title":"よくある質問","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"c7994b9def793939c4c5afb4b1c93895ee25fc64f1f989d63460add3f098ee05","order":40},"headers":[],"relativePath":"ja/user/preferences/faq.md","filePath":"ja/user/preferences/faq.md","lastUpdated":1794611623000}'),o={name:"ja/user/preferences/faq.md"};function n(i,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions" tabindex="-1">よくある質問 <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;よくある質問 {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>データや認証情報を変える前に、操作上のよくある混同を解消します。以下の確認には起動中のデスクトップアプリが必要です。対応パッケージは<a href="./../requirements.html">動作要件</a> を参照します。実験段階やサービス依存と明示されたものを除き、ここで扱うローカル機能は利用可能です。</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">Cloud サインインで TikTok に接続できますか？ <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;Cloud サインインで TikTok に接続できますか？ {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>できません。<a href="./../live/connections.html">接続</a> で配信者を選び、別途 LIVE を開始します。Cloud ID はアカウント方式サービス用です。TikTok Cookie は接続用の専用マスク欄だけに入力します。</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">接続済みなのにフィードが空なのはなぜですか？ <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;接続済みなのにフィードが空なのはなぜですか？ {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>静かなルームでは新規イベントがないことがあります。全イベントを選び、検索を消してスクロールを再開し、接続状態を確認します。スクロール停止中も取り込みと自動化は動きます。フィード消去でポイントや保存統計はリセットされません。</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">統計は現在のセッションだけですか？ <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;統計は現在のセッションだけですか？ {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>現在の <a href="./../points/statistics.html">分析</a> は選択した配信者と期間の保存済み集計を照会します。日付を広げて更新すると過去の記録を調べられます。チャットの全記録ではありません。ポイント残高は別ルールで、手動や自動化の調整を含む場合があります。</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">テンプレート・変数・ランキングはどこにありますか？ <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;テンプレート・変数・ランキングはどこにありますか？ {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>テンプレートとプロファイルは <a href="./../automations/templates.html">自動化</a>、プラグインの「探す」はプラグイン用です。実行時の値は自動化の変数にあります。実験的なランキングとコンテストは <code>#/rankings</code> にありますが、メインナビゲーションと起動時復元から隠されています。通常のポイント順位表とフィードの順位パネルは別画面です。</p><h2 id="does-saving-synchronize-everything" tabindex="-1">保存するとすべて同期されますか？ <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;保存するとすべて同期されますか？ {#does-saving-synchronize-everything}&quot;">​</a></h2><p>されません。イベント／アクション変更はローカル基準との比較です。変数の保存はローカルで、対応時に別途確認付きの送信・採用・取り下げを行います。秘密値の比較はマスクされます。Cloud オーバーレイは作成・改訂とライブラリ操作を使い、この版に共有オーバーレイの変更アダプターはありません。方向を選ぶ前に <a href="./../cloud/changes.html">変更</a> を読んでください。</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">テストは無害ですか？取り込むとすぐ実行されますか？ <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;テストは無害ですか？取り込むとすぐ実行されますか？ {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>テストは音声、ネットワーク要求、ポイント変更などを実行できます。まず <a href="./../automations/first-rule.html">core.log</a> を使います。取り込んだ定義は無効のままなので、確認後に明示的に有効化します。プラグインもインストールだけでなくサービス設定が必要です。</p><h2 id="expected-result-and-recovery" tabindex="-1">期待される結果と対処 <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;期待される結果と対処 {#expected-result-and-recovery}&quot;">​</a></h2><p>リセットせずに担当ページを特定できるはずです。自動更新確認は任意で、自動インストールは実験段階かつ現行リリースの条件で無効です。完全なリモート共同操作と本番のニックネーム検索は配置と実動作確認に依存します。不明点が残れば<a href="./backups.html">バックアップ</a> を取り、バージョン、時刻、再現手順を含む<a href="./troubleshooting.html">診断レポート</a> を集めます。</p>',17)])])}const p=a(o,[["render",n]]);export{f as __pageData,p as default};
